import { test, expect } from '@playwright/test';

test.describe('Form Data Persistence', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual form URL
  });

  test('should retain form data after navigating away', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'John Doe');
    await page.fill(getByLabel('Email'), 'john.doe@example.com');

    await page.click(getByText('Navigate Away')); // Replace with the actual navigation action
    await page.goBack();

    const nameValue = await page.inputValue(getByLabel('Name'));
    const emailValue = await page.inputValue(getByLabel('Email'));

    expect(nameValue).toBe('John Doe');
    expect(emailValue).toBe('john.doe@example.com');
  });

  test('should not lose data on page refresh', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'Jane Doe');
    await page.fill(getByLabel('Email'), 'jane.doe@example.com');

    await page.reload();

    const nameValue = await page.inputValue(getByLabel('Name'));
    const emailValue = await page.inputValue(getByLabel('Email'));

    expect(nameValue).toBe('Jane Doe');
    expect(emailValue).toBe('jane.doe@example.com');
  });
});
